from __future__ import annotations

from typing import Optional

from tracker.service.tracker_service import TrackerService
from tracker.service.reporting import format_issue, format_issue_list
from tracker.interface.parser import parse_command


class CommandRouter:
    def __init__(self, service: TrackerService) -> None:
        self._svc = service

    def handle(self, line: str) -> str:
        cmd = parse_command(line)
        if cmd is None:
            return "ERROR: unrecognised command"

        name = cmd["command"]

        if name == "create":
            issue = self._svc.create_issue(
                title=cmd["title"],
                template_name=cmd.get("template"),
            )
            return f"Created {issue.id}"

        if name == "list":
            return format_issue_list(self._svc.list_issues())

        if name == "show":
            issue = self._svc.get_issue(cmd["id"])
            if issue is None:
                return f"ERROR: issue {cmd['id']!r} not found"
            return format_issue(issue)

        if name == "add-label":
            issue = self._svc.add_label(cmd["id"], cmd["label"])
            if issue is None:
                return f"ERROR: issue {cmd['id']!r} not found"
            return format_issue(issue)

        if name == "remove-label":
            issue = self._svc.remove_label(cmd["id"], cmd["label"])
            if issue is None:
                return f"ERROR: issue {cmd['id']!r} not found"
            return format_issue(issue)

        if name == "set-priority":
            issue = self._svc.set_priority(cmd["id"], cmd["priority"])
            if issue is None:
                return f"ERROR: issue {cmd['id']!r} not found"
            return format_issue(issue)

        return f"ERROR: unhandled command {name!r}"
