from __future__ import annotations

import re
from typing import Optional


def parse_command(line: str) -> Optional[dict]:
    line = line.strip()

    # create "title" [--template bug]
    m = re.match(r'^create\s+"([^"]+)"(?:\s+--template\s+(\S+))?$', line)
    if m:
        result = {"command": "create", "title": m.group(1)}
        if m.group(2):
            result["template"] = m.group(2)
        return result

    # list
    if line == "list":
        return {"command": "list"}

    # show <id>
    m = re.match(r'^show\s+(\S+)$', line)
    if m:
        return {"command": "show", "id": m.group(1)}

    # add-label <id> <label>
    m = re.match(r'^add-label\s+(\S+)\s+(\S+)$', line)
    if m:
        return {"command": "add-label", "id": m.group(1), "label": m.group(2)}

    # remove-label <id> <label>
    m = re.match(r'^remove-label\s+(\S+)\s+(\S+)$', line)
    if m:
        return {"command": "remove-label", "id": m.group(1), "label": m.group(2)}

    # set-priority <id> <priority>
    m = re.match(r'^set-priority\s+(\S+)\s+(\d+)$', line)
    if m:
        return {"command": "set-priority", "id": m.group(1), "priority": int(m.group(2))}

    return None
